func swimInWater(grid [][]int) int {
    n := len(grid)
    minH, maxH := grid[0][0], grid[0][0]
    for r := 0; r < n; r++ {
        for c := 0; c < n; c++ {
            if grid[r][c] < minH {
                minH = grid[r][c]
            }
            if grid[r][c] > maxH {
                maxH = grid[r][c]
            }
        }
    }

    visit := make([][]bool, n)
    for i := range visit {
        visit[i] = make([]bool, n)
    }

    var dfs func(r, c, t int) bool
    dfs = func(r, c, t int) bool {
        if r < 0 || c < 0 || r >= n || c >= n ||
           visit[r][c] || grid[r][c] > t {
            return false
        }
        if r == n-1 && c == n-1 {
            return true
        }
        visit[r][c] = true
        found := dfs(r+1, c, t) || dfs(r-1, c, t) ||
                 dfs(r, c+1, t) || dfs(r, c-1, t)
        return found
    }

    for t := minH; t <= maxH; t++ {
        if dfs(0, 0, t) {
            return t
        }
        for i := range visit {
            for j := range visit[i] {
                visit[i][j] = false
            }
        }
    }

    return maxH
}
