                || dfs(grid, visit, r - 1, c, t)
                || dfs(grid, visit, r, c + 1, t)
                || dfs(grid, visit, r, c - 1, t)
        }

        let (mut lo, mut hi) = (min_h, max_h);
        while lo < hi {
            let mid = (lo + hi) >> 1;
            if dfs(&grid, &mut visit, 0, 0, mid) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
            for row in visit.iter_mut() {
                row.fill(false);
