class Solution {
    /**
     * @param {number[][]} grid
     * @return {number}
     */
    swimInWater(grid) {
        const N = grid.length;
        const visit = new Set();
        const minPQ = new MinPriorityQueue(entry => entry[0]);
        const directions = [
            [0, 1],
            [0, -1],
            [1, 0],
            [-1, 0],
        ];

        minPQ.enqueue([grid[0][0], 0, 0]);
        visit.add('0,0');

        while (!minPQ.isEmpty()) {
            const [t, r, c] = minPQ.dequeue();
            if (r === N - 1 && c === N - 1) {
                return t;
            }
            for (const [dr, dc] of directions) {
                const neiR = r + dr;
                const neiC = c + dc;
                if (
                    neiR < 0 ||
                    neiC < 0 ||
                    neiR >= N ||
                    neiC >= N ||
                    visit.has(`${neiR},${neiC}`)
